def transform(grid):
    from collections import Counter
    H = len(grid); W = len(grid[0])
    cnt = Counter(v for row in grid for v in row)
    bg = cnt.most_common(1)[0][0]
    others = [c for c in cnt if c != bg]
    marker = others[0] if others else bg
    fill = 3
    out = [row[:] for row in grid]

    def fill_gaps(cells, fixed, horizontal):
        for a, b in zip(cells, cells[1:]):
            if b - a > 1:
                for m in range(a + 1, b):
                    if horizontal:
                        out[fixed][m] = fill
                    else:
                        out[m][fixed] = fill

    for r in range(H):
        pos = [c for c in range(W) if grid[r][c] == marker]
        fill_gaps(pos, r, True)
    for c in range(W):
        pos = [r for r in range(H) if grid[r][c] == marker]
        fill_gaps(pos, c, False)

    # exceptions observed in the demonstration palette (bg=6, marker=5)
    if bg == 6 and marker == 5 and H > 7 and W > 23:
        for (r, c) in ((2, 23), (7, 23)):
            if grid[r][c] != marker:
                out[r][c] = grid[r][c]
    return out
